import java.io.*;
import java.util.*;
import com.yahoo.labs.samoa.instances.*;
import moa.cluster.Cluster;
import moa.cluster.Clustering;
import moa.evaluation.CMM;
import moa.gui.visualization.DataPoint;

/** Reads cases.txt, scores each hard partition with MOA's CMM, prints the eight readings. */
public class CMMHarness {
    /** A found cluster = the points with one predicted label (by timestamp). */
    static class LabelCluster extends Cluster {
        final Set<Integer> members = new HashSet<>();
        final int d;
        LabelCluster(int d, int id) { this.d = d; setId(id); }
        public double[] getCenter() { return new double[d]; }
        public double getWeight() { return members.size(); }
        public double getInclusionProbability(Instance inst) {
            return (inst instanceof DataPoint && members.contains(((DataPoint) inst).getTimestamp())) ? 1.0 : 0.0;
        }
        public Instance sample(Random random) { return null; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new FileReader(args[0]));
        PrintStream realOut = System.out;
        System.setOut(new PrintStream(new ByteArrayOutputStream()));  // MOA prints debugging noise
        String line;
        while ((line = in.readLine()) != null) {
            String[] h = line.trim().split(" ");
            String name = h[1];
            int n = Integer.parseInt(h[2]), d = Integer.parseInt(h[3]), K = Integer.parseInt(h[4]);
            boolean hasNoise = h[5].equals("1"), explicitW = h[6].equals("1");
            ArrayList<Attribute> atts = new ArrayList<>();
            for (int j = 0; j < d; j++) atts.add(new Attribute("a" + j));
            List<String> vals = new ArrayList<>();
            for (int j = 0; j < K; j++) vals.add("c" + j);
            if (hasNoise) vals.add("noise");
            if (vals.isEmpty()) vals.add("c0");
            atts.add(new Attribute("class", vals));
            Instances header = new Instances("cmm", atts, n);
            header.setClassIndex(d);
            ArrayList<DataPoint> points = new ArrayList<>();
            Map<Integer, LabelCluster> clusters = new LinkedHashMap<>();
            double[] w = new double[n];
            for (int i = 0; i < n; i++) {
                String[] t = in.readLine().trim().split(" ");
                double[] v = new double[d + 1];
                for (int j = 0; j < d; j++) v[j] = Double.parseDouble(t[j]);
                v[d] = Integer.parseInt(t[d]);
                int pred = Integer.parseInt(t[d + 1]);
                w[i] = Double.parseDouble(t[d + 2]);
                DenseInstance inst = new DenseInstance(1.0, v);
                inst.setDataset(header);
                DataPoint p = new DataPoint(inst, i + 1);
                points.add(p);
                if (pred >= 0) {
                    clusters.computeIfAbsent(pred, k -> new LabelCluster(d, k)).members.add(i + 1);
                }
            }
            // BatchCmd: decay_rate = -ln(threshold)/horizon, weight = 2^(-rate * age) at the last timestamp
            double rate = (-1 * Math.log(0.01) / n);
            for (int i = 0; i < n; i++) {
                if (explicitW) points.get(i).setWeight(w[i]);
                else points.get(i).updateWeight(n, rate);
            }
            Clustering gt = new Clustering(points);
            Clustering found = new Clustering(clusters.values().toArray(new Cluster[0]));
            CMM cmm = new CMM();
            StringBuilder sb = new StringBuilder(name);
            try {
                cmm.evaluateClusteringPerformance(found, gt, points);
                for (int m = 0; m < cmm.getNumMeasures(); m++) sb.append(" ").append(cmm.getLastValue(m));
            } catch (Exception ex) {
                sb.append(" ERROR ").append(ex.getClass().getSimpleName());
            }
            StringBuilder ws = new StringBuilder();
            for (int i = 0; i < n; i++) ws.append(i == 0 ? "" : " ").append(points.get(i).weight());
            realOut.println(sb);
            realOut.println("W " + name + " " + ws);
        }
    }
}
